import{_ as t,o as a,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Zendure HA local MQTT","description":"Set up local MQTT for Zendure legacy devices.","frontmatter":{"title":"Zendure HA local MQTT","description":"Set up local MQTT for Zendure legacy devices."},"headers":[],"relativePath":"en/collection/zendure-ha/lokales-mqtt.md","filePath":"en/collection/zendure-ha/lokales-mqtt.md","lastUpdated":1793447386000}'),i={name:"en/collection/zendure-ha/lokales-mqtt.md"};function n(d,e,l,s,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<p><a id="zendure-ha-lokales-mqtt"></a><a id="current-focus"></a></p><h1 id="lokales-mqtt" tabindex="-1">Local MQTT <a class="header-anchor" href="#lokales-mqtt" aria-label="Permalink to &quot;Local MQTT {#lokales-mqtt}&quot;">​</a></h1><p>According to the original wiki, local MQTT is particularly relevant for Zendure legacy devices:</p><ul><li>Hyper2000</li><li>Hub2000</li><li>Hub1200</li><li>Ace1500</li></ul><p>Newer devices such as SolarFlow 800, SolarFlow 800 Pro and SolarFlow 2400 can communicate via <code>zenSDK</code> and typically do not require local MQTT.</p><h2 id="voraussetzungen" tabindex="-1">Requirements <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Requirements {#voraussetzungen}&quot;">​</a></h2><ul><li>MQTT broker in Home Assistant, for example Mosquitto</li><li>Bluetooth integration in Home Assistant</li><li>Zendure device must be visible via Bluetooth</li><li>WiFi SSID and WiFi password</li><li>MQTT user and password</li></ul><div class="warning custom-block"><p class="custom-block-title">MQTT address</p><p>A real network address or IP address should be used as the MQTT server address. According to the original wiki, <code>core-mosquitto</code> is not a suitable network address for the Zendure devices.</p></div><h2 id="einrichtungsdaten" tabindex="-1">Setup data <a class="header-anchor" href="#einrichtungsdaten" aria-label="Permalink to &quot;Setup data {#einrichtungsdaten}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>field</th><th>Example/Note</th></tr></thead><tbody><tr><td>MQTT server</td><td>IP address or hostname of the broker</td></tr><tr><td>MQTT port</td><td>mostly <code>1883</code></td></tr><tr><td>MQTT user</td><td>Username on the broker</td></tr><tr><td>MQTT password</td><td>Password on the broker</td></tr><tr><td>WiFi SSID</td><td>WLAN into which the device should be integrated</td></tr><tr><td>WiFi password</td><td>Password of this WLAN</td></tr></tbody></table><h2 id="verbindungsart-pro-gerat" tabindex="-1">Connection type per device <a class="header-anchor" href="#verbindungsart-pro-gerat" aria-label="Permalink to &quot;Connection type per device {#verbindungsart-pro-gerat}&quot;">​</a></h2><p>For supported devices, the connection type can be selected for each device:</p><ul><li><code>cloud</code></li><li><code>local</code></li><li>depending on the device also <code>zenSDK</code></li></ul><p>When changing the connection type, the integration tries to set the MQTT server in the device via Bluetooth. The device can restart. The process may take a few seconds and will then generate a Home Assistant notification with success or failure.</p><h2 id="reset-verbindung" tabindex="-1">Reset connection <a class="header-anchor" href="#reset-verbindung" aria-label="Permalink to &quot;Reset connection {#reset-verbindung}&quot;">​</a></h2><p>For legacy devices, the integration provides a button <code>Reset Verbindung</code>. This can be used if the MQTT conversion was not completed properly.</p><p>Original wiki:</p><ul><li><a href="https://github.com/Zendure/Zendure-HA/wiki/Local-Mqtt-(Legacy-Devices)" target="_blank" rel="noreferrer">Local MQTT (Legacy Devices)</a></li></ul>',18)])])}const T=t(i,[["render",n]]);export{p as __pageData,T as default};
